BEGIN_HEADER_PROLOGUE
#include <bitset>
END_HEADER_PROLOGUE

std::bitset<5> reg4;

// bits 0 and 2 are reserved
reg4[1] = get_resolution();
reg4[3] = get_output_format();
reg4[4] = get_SB_first();

return (uint8_t) reg4.to_ulong();

if ( get_gain() == 1 ) {
  return ( get_offset() <= 2700);
} else if ( get_gain() == 2 ) {
  return ( get_offset() <= 1500 );
}
return false;

BEGIN_HEADER_PROLOGUE
#include <bitset>
END_HEADER_PROLOGUE

std::bitset<16> reg52;
decltype(reg52) clamp(get_clamp());
clamp <<= 6;

reg52[12] = get_integrator_disable();

decltype(reg52) gain(get_gain());
clamp <<= 13;

reg52 |= clamp;
reg52 |= gain;

return (uint16_t) reg52.to_ulong() ;



std::bitset<14> reg51(get_lpf_cut_frequency());
reg51 <<= 1;
reg51[4] = get_integrator_disable();
reg51[7] = true;  // clamp is always disabled and we are in low noise mode
reg51[13] = get_gain();

return (uint16_t) reg51.to_ulong() ;

auto cut = get_lpf_cut_frequency();
if (cut != 0 && cut != 2 && cut != 4 ) return false;
return true;

